import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.YiAtXB4p.js";const u=JSON.parse('{"title":"Legacy removal","description":"","frontmatter":{"title":"Legacy removal","sourceFile":"guides/LEGACY-REMOVAL.md"},"headers":[],"relativePath":"guide/legacy-removal.md","filePath":"guide/legacy-removal.md"}'),r={name:"guide/legacy-removal.md"};function a(s,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="legacy-removal" tabindex="-1">Legacy removal <a class="header-anchor" href="#legacy-removal" aria-label="Permalink to &quot;Legacy removal&quot;">​</a></h1><p><strong>Implements:</strong> <code>REL-06</code> · see <a href="./charter">CHARTER.md</a> Part 8 and <a href="./semver#deprecate-before-you-remove">SEMVER.md</a>. <strong>Checked by:</strong> <code>tests/tdd/scripts/legacy-removal.test.ts</code>.</p><p>13.0.0 removes the legacy construction tree. From then on <code>createEsi()</code> from <code>@lgriffin/esi.ts/client</code> is the only way to call ESI: one runtime, <code>esi.public</code> for the operations that need no scope and <code>esi.as(identity)</code> for the rest, over the operations generated from the vendored OpenAPI document (<a href="./multi-character">MULTI-CHARACTER.md</a>).</p><p><a href="./semver#deprecate-before-you-remove">SEMVER.md</a> requires a minor release to mark a surface <code>@deprecated</code> before a major release removes it. 12.1.0 is that release for everything in the table below. Each name carries a <code>@deprecated</code> JSDoc tag that names <code>createEsi()</code>, so editors strike it through and TypeDoc flags it. Nothing logs a warning at runtime, and nothing changes behaviour before 13.0.0.</p><p>This page is the manifest. It lists every surface 13.0.0 takes away, what replaces it, and the capabilities <code>createEsi()</code> does not offer yet. A test reads the table and fails if any name in it is missing from the API report (<code>etc/esi.ts.api.md</code>) or is not marked <code>@deprecated</code> there.</p><hr><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><p>Every row is exported from the root entry (<code>@lgriffin/esi.ts</code>). In the replacement column, <code>esi</code> is <code>createEsi({ userAgent })</code> and <code>tokens</code> is an <code>EsiTokenManager</code>.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Kind</th><th>Deprecated since</th><th>Replacement</th><th>Removed in</th></tr></thead><tbody><tr><td><code>EsiClient</code></td><td>class</td><td>12.1.0</td><td><code>createEsi({ userAgent })</code>, then <code>esi.public</code> and <code>esi.as(identity)</code></td><td>13.0.0</td></tr><tr><td><code>getDefaultClient</code></td><td>function</td><td>12.1.0</td><td>Build one runtime with <code>createEsi()</code> and share it</td><td>13.0.0</td></tr><tr><td><code>EsiClientBuilder</code></td><td>class</td><td>12.1.0</td><td><code>createEsi()</code>; every domain is on every view, so there is nothing to choose</td><td>13.0.0</td></tr><tr><td><code>CustomEsiClient</code></td><td>class</td><td>12.1.0</td><td><code>createEsi()</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory</code></td><td>class</td><td>12.1.0</td><td><code>createEsi()</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createClient</code></td><td>method</td><td>12.1.0</td><td><code>esi.public</code> or <code>esi.as(identity)</code>, then the domain</td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createAllianceClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.public.alliance(allianceId)</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createCharacterClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.public.character(characterId)</code>, <code>esi.as(identity).character(characterId)</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createCorporationClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.public.corporation(corporationId)</code>, <code>esi.as(identity).corporation(corporationId)</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createMarketClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.public.markets</code>, <code>esi.public.market(regionId)</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createUniverseClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.public.universe</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createFleetClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.as(identity).fleet(fleetId)</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createAssetsClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.as(identity).character(characterId).assets</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createWalletClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.as(identity).character(characterId).wallet</code></td><td>13.0.0</td></tr><tr><td><code>EsiApiFactory.createMailClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.as(identity).character(characterId).mail</code></td><td>13.0.0</td></tr><tr><td><code>ApiClientType</code></td><td>type</td><td>12.1.0</td><td>None needed: the scope tree has every domain</td><td>13.0.0</td></tr><tr><td><code>ApiClientBuilder</code></td><td>class</td><td>12.1.0</td><td><code>createEsi()</code>; <code>transport</code> replaces <code>setFetch</code> (custom cache, limiter and breaker: gap G11)</td><td>13.0.0</td></tr><tr><td><code>BaseEsiClient</code></td><td>class</td><td>12.1.0</td><td>The generated operations; no subclassing</td><td>13.0.0</td></tr><tr><td><code>RouteOptions</code></td><td>interface</td><td>12.1.0</td><td>The spec&#39;s route request body: <code>esi.public.route(origin, destination).post(body)</code></td><td>13.0.0</td></tr><tr><td><code>EsiTokenManager.createClient</code></td><td>method</td><td>11.0.0</td><td><code>esi.as(tokens.identity(characterId))</code></td><td>13.0.0</td></tr><tr><td><code>ManagedClientConfig</code></td><td>type</td><td>12.1.0</td><td>The same settings on <code>createEsi()</code></td><td>13.0.0</td></tr><tr><td><code>ApiClient</code></td><td>class</td><td>12.1.0</td><td><code>createEsi()</code> builds and configures its own pipeline (custom middleware: G11)</td><td>13.0.0</td></tr><tr><td><code>configureApiClient</code></td><td>function</td><td>12.1.0</td><td><code>EsiOptions</code> on <code>createEsi()</code></td><td>13.0.0</td></tr><tr><td><code>ConfigureApiClientResult</code></td><td>type</td><td>12.1.0</td><td>None needed, with <code>configureApiClient</code></td><td>13.0.0</td></tr><tr><td><code>EsiClientConfig</code></td><td>type</td><td>12.1.0</td><td><code>EsiOptions</code> (differences: G12)</td><td>13.0.0</td></tr><tr><td><code>buildEndpointPath</code></td><td>function</td><td>12.1.0</td><td>None needed: generated operations build their own requests</td><td>13.0.0</td></tr><tr><td><code>DeprecationInfo</code></td><td>type</td><td>12.1.0</td><td>Deprecation data on generated operations (G3)</td><td>13.0.0</td></tr><tr><td><code>CreateClientOptions</code></td><td>type</td><td>12.1.0</td><td>Metadata and safe-mode views (G8)</td><td>13.0.0</td></tr><tr><td><code>WithMetadata</code></td><td>type</td><td>12.1.0</td><td>Metadata view (G8)</td><td>13.0.0</td></tr><tr><td><code>WithSafeMode</code></td><td>type</td><td>12.1.0</td><td>Safe-mode view (G8)</td><td>13.0.0</td></tr><tr><td><code>InferEndpointResult</code></td><td>type</td><td>12.1.0</td><td><code>Awaited&lt;ReturnType&lt;…&gt;&gt;</code> on the scope-tree call (named types: G14)</td><td>13.0.0</td></tr><tr><td><code>UnwrapArray</code></td><td>type</td><td>12.1.0</td><td>None needed, with the endpoint maps</td><td>13.0.0</td></tr><tr><td><code>CursorOptions</code></td><td>type</td><td>12.1.0</td><td><code>before</code> and <code>after</code> on the generated cursor operation (G7)</td><td>13.0.0</td></tr><tr><td><code>CursorResult</code></td><td>type</td><td>12.1.0</td><td>The generated operation&#39;s body, cursor included (G7)</td><td>13.0.0</td></tr><tr><td><code>CursorTokens</code></td><td>type</td><td>12.1.0</td><td>The generated body&#39;s <code>cursor</code> (G7)</td><td>13.0.0</td></tr><tr><td><code>fetchAllCursorPages</code></td><td>function</td><td>12.1.0</td><td>A follower for generated cursor operations (G7)</td><td>13.0.0</td></tr><tr><td><code>fetchAllPages</code></td><td>function</td><td>12.1.0</td><td><code>for await</code> over a page-paginated operation; concurrency: G6</td><td>13.0.0</td></tr><tr><td><code>fetchPages</code></td><td>function</td><td>12.1.0</td><td><code>for await</code> over a page-paginated operation; page-level iteration: G6</td><td>13.0.0</td></tr><tr><td><code>PageResult</code></td><td>type</td><td>12.1.0</td><td>Page-level iteration (G6)</td><td>13.0.0</td></tr><tr><td><code>batchFetch</code></td><td>function</td><td>12.1.0</td><td>Batch helper for generated operations (G13)</td><td>13.0.0</td></tr><tr><td><code>batchPost</code></td><td>function</td><td>12.1.0</td><td>Batch helper for generated operations (G13)</td><td>13.0.0</td></tr><tr><td><code>BatchOptions</code></td><td>type</td><td>12.1.0</td><td>With <code>batchFetch</code> (G13)</td><td>13.0.0</td></tr><tr><td><code>BatchResult</code></td><td>type</td><td>12.1.0</td><td>With <code>batchFetch</code> (G13)</td><td>13.0.0</td></tr><tr><td><code>EsiDiagnostics</code></td><td>class</td><td>12.1.0</td><td>Diagnostics on <code>createEsi()</code> (G9)</td><td>13.0.0</td></tr><tr><td><code>CacheStats</code></td><td>type</td><td>12.1.0</td><td>Diagnostics on <code>createEsi()</code> (G9)</td><td>13.0.0</td></tr><tr><td><code>CircuitBreakerStats</code></td><td>type</td><td>12.1.0</td><td>Diagnostics on <code>createEsi()</code> (G9)</td><td>13.0.0</td></tr><tr><td><code>AccessListsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId).accessLists</code></td><td>13.0.0</td></tr><tr><td><code>AllianceClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.alliance(allianceId)</code>, <code>esi.public.alliances</code></td><td>13.0.0</td></tr><tr><td><code>AssetsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity)</code>: <code>.character(id).assets</code>, <code>.corporation(id).assets</code></td><td>13.0.0</td></tr><tr><td><code>CalendarClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId).calendar</code></td><td>13.0.0</td></tr><tr><td><code>CharacterClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.character(characterId)</code>, <code>esi.as(identity).character(characterId)</code></td><td>13.0.0</td></tr><tr><td><code>CharacterSkillsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId).skills</code></td><td>13.0.0</td></tr><tr><td><code>ClonesClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId).clones</code></td><td>13.0.0</td></tr><tr><td><code>ContactsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity)</code>: <code>.character(id).contacts</code>, <code>.corporation(id).contacts</code>, <code>.alliance(id).contacts</code></td><td>13.0.0</td></tr><tr><td><code>ContractsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.contracts</code>, <code>esi.as(identity).character(characterId).contracts</code></td><td>13.0.0</td></tr><tr><td><code>CorporationProjectsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).corporation(corporationId).projects</code></td><td>13.0.0</td></tr><tr><td><code>CorporationsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.corporation(corporationId)</code>, <code>esi.as(identity).corporation(corporationId)</code></td><td>13.0.0</td></tr><tr><td><code>CosmeticsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public</code> and <code>esi.as(identity)</code> cosmetics operations</td><td>13.0.0</td></tr><tr><td><code>DogmaClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.dogma</code></td><td>13.0.0</td></tr><tr><td><code>FactionClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.fw</code></td><td>13.0.0</td></tr><tr><td><code>FittingsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId).fittings</code></td><td>13.0.0</td></tr><tr><td><code>FleetClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).fleet(fleetId)</code></td><td>13.0.0</td></tr><tr><td><code>FreelanceJobsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.freelanceJobs</code>, <code>esi.as(identity)</code> freelance-job operations</td><td>13.0.0</td></tr><tr><td><code>IncursionsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.incursions</code></td><td>13.0.0</td></tr><tr><td><code>IndustryClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.industry</code>, <code>esi.as(identity)</code> industry and mining operations</td><td>13.0.0</td></tr><tr><td><code>InsuranceClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.insurance</code></td><td>13.0.0</td></tr><tr><td><code>KillmailsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.killmail(killmailId, hash)</code>, <code>esi.as(identity)</code> recent-killmail operations</td><td>13.0.0</td></tr><tr><td><code>LocationClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId)</code> location, online and ship</td><td>13.0.0</td></tr><tr><td><code>LoyaltyClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.loyalty</code>, <code>esi.as(identity).character(characterId).loyalty</code></td><td>13.0.0</td></tr><tr><td><code>MailClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId).mail</code></td><td>13.0.0</td></tr><tr><td><code>MarketClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.markets</code>, <code>esi.public.market(regionId)</code>, <code>esi.as(identity)</code> order operations</td><td>13.0.0</td></tr><tr><td><code>MercenaryClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId)</code> mercenary operations</td><td>13.0.0</td></tr><tr><td><code>MetaClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.meta</code>; the OpenAPI document routes have no replacement yet (gap G4)</td><td>13.0.0</td></tr><tr><td><code>MilitaryCampaignsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.militaryCampaigns</code>, <code>esi.public.militaryCampaign(campaignId)</code></td><td>13.0.0</td></tr><tr><td><code>ParagonHubClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.paragonHub</code>, <code>esi.as(identity)</code> Paragon Hub operations</td><td>13.0.0</td></tr><tr><td><code>PiClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.universe</code> schematics, <code>esi.as(identity).character(characterId).planets</code></td><td>13.0.0</td></tr><tr><td><code>RouteClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.route(origin, destination).post(body)</code></td><td>13.0.0</td></tr><tr><td><code>SearchClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).character(characterId).search</code></td><td>13.0.0</td></tr><tr><td><code>SkyhooksClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.skyhooks</code>, <code>esi.as(identity)</code> skyhook operations</td><td>13.0.0</td></tr><tr><td><code>SovereigntyClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.sovereignty</code></td><td>13.0.0</td></tr><tr><td><code>StatusClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.status</code></td><td>13.0.0</td></tr><tr><td><code>UiClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity).ui</code></td><td>13.0.0</td></tr><tr><td><code>UniverseClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.universe</code></td><td>13.0.0</td></tr><tr><td><code>WalletClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.as(identity)</code>: <code>.character(id).wallet</code>, <code>.corporation(id).wallets</code></td><td>13.0.0</td></tr><tr><td><code>WarsClient</code></td><td>class</td><td>12.1.0</td><td><code>esi.public.wars</code>, <code>esi.public.war(warId)</code></td><td>13.0.0</td></tr></tbody></table><p>The pipeline rows from <code>ApiClient</code> to <code>CircuitBreakerStats</code> are root names only. <code>createEsi()</code> and the request pipeline still use the declarations behind them, so the root entry exports deprecated aliases (<code>src/legacyExports.ts</code>) instead of tagging the declarations, and the API report shows each as an alias of an unexported <code>…_2</code> symbol. 13.0.0 removes the names from the root entry; the internals stay.</p><h3 id="whole-modules" tabindex="-1">Whole modules <a class="header-anchor" href="#whole-modules" aria-label="Permalink to &quot;Whole modules&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module</th><th>Entry</th><th>Deprecated since</th><th>How it is marked</th><th>Replacement</th><th>Removed in</th></tr></thead><tbody><tr><td>Hand-written response types (<code>src/types</code>, 194 types such as <code>MarketOrder</code>)</td><td>root</td><td>12.1.0</td><td>Each type tagged</td><td><code>Awaited&lt;ReturnType&lt;…&gt;&gt;</code> on the scope-tree call; nameable generated types: G14</td><td>13.0.0</td></tr><tr><td><code>TestDataFactory</code></td><td><code>./testing</code></td><td>12.1.0</td><td>Class tagged</td><td><code>createMockTransport()</code> answering with the spec&#39;s shapes; typed fixtures: G14</td><td>13.0.0</td></tr><tr><td>Hand-written Zod schemas</td><td><code>./schemas</code>, and the root <code>schemas</code> namespace</td><td>12.1.0</td><td>Module documentation only</td><td>Generated operations&#39; runtime validation (G1)</td><td>13.0.0, unless G1 keeps them</td></tr></tbody></table><p>The schemas carry no tag. A tag on each of the 225 would flag the endpoint maps, the response types and every schema test instead of consumers&#39; uses, and aliasing the root <code>schemas</code> namespace to tag it would drop every schema from the API report, which is how a tightened schema is caught as a break (<a href="./semver#runtime-behaviour">SEMVER.md</a>). The branded ID types and <code>brand</code> in <code>src/types/branded.ts</code> are not response types and are not deprecated; <code>src/auth</code> uses <code>CharacterId</code>.</p><p>Internal modules go with them and need no deprecation, since no entry point exports them: <code>src/clients/ClientRegistry.ts</code> (<code>createClientInstance</code>, <code>ClientInstance</code>, marked <code>@deprecated</code> anyway), the 39 endpoint maps in <code>src/core/endpoints/*Endpoints.ts</code> and <code>createClient()</code>.</p><p>The scope-tree paths in the table are the generated ones in <code>src/generated/operations.generated.ts</code>; an editor completes the rest of each path. Every one of the 235 routes in the legacy endpoint maps has a generated operation except the two in gap G4. The beta routes (SKINR and the rest of Paragon Hub, military campaigns, freelance jobs, corporation projects) are all in the vendored spec and generated.</p><hr><h2 id="parity-gaps" tabindex="-1">Parity gaps <a class="header-anchor" href="#parity-gaps" aria-label="Permalink to &quot;Parity gaps&quot;">​</a></h2><p>What a consumer can do through the legacy surfaces that <code>createEsi()</code>, <code>esi.public</code> and <code>esi.as(identity)</code> do not offer equivalently, measured against <code>master</code> on 2026-10-16. <strong>Must close</strong> marks a gap that has to be closed, or a documented decision to drop the capability recorded here, before 13.0.0 ships.</p><table tabindex="0"><thead><tr><th>ID</th><th>Gap</th><th>Evidence</th><th>Must close</th></tr></thead><tbody><tr><td>G1</td><td><strong>Response validation.</strong> Generated operations return the body unvalidated, so <code>validateResponse</code> on <code>EsiOptions</code> does nothing; 216 of the 235 legacy endpoint definitions carry a Zod <code>responseSchema</code>. A separate pull request is closing this.</td><td><code>src/adapters/PipelineTransport.ts</code> returns <code>response.body</code>; <code>src/core/endpoints/createClient.ts</code> runs <code>safeParse</code></td><td>Yes</td></tr><tr><td>G2</td><td><strong>Request validation.</strong> <code>validateRequest</code> on <code>EsiOptions</code> is accepted and ignored: no generated operation has a request schema. Five legacy routes validate their body (<code>addContacts</code>, <code>updateFleet</code>, <code>sendMail</code>, <code>postBulkNamesToIds</code>, <code>postNamesAndCategories</code>).</td><td><code>PipelineTransport.request</code> never reads a schema; <code>createClient.ts</code> checks <code>def.requestSchema</code></td><td>Yes</td></tr><tr><td>G3</td><td><strong>Endpoint deprecation warnings.</strong> <code>OperationMeta.deprecated</code> is a boolean nothing reads, with no message, replacement or sunset date. The legacy <code>DeprecationInfo</code> logs a warning per call, and step 1 of SEMVER.md&#39;s deprecation process depends on it. No operation is deprecated today.</td><td><code>src/core/ports/OperationTransport.ts</code>, <code>PipelineTransport.ts</code>; <code>createClient.ts</code> <code>def.deprecated</code></td><td>Yes</td></tr><tr><td>G4</td><td><strong>The OpenAPI document routes.</strong> <code>GET meta/openapi.json</code> and <code>GET meta/openapi.yaml</code> (<code>MetaClient.getOpenApiJson</code>, <code>getOpenApiYaml</code>) are not paths in the spec, so nothing is generated for them, and the YAML one needs a text response, which <code>PipelineTransport</code> cannot request.</td><td><code>scripts/spec/esi-endpoint-exceptions.json</code>; <code>metaEndpoints.ts</code> <code>textResponse</code></td><td>Yes</td></tr><tr><td>G5</td><td><strong>Empty public contract answers.</strong> ESI answers an expired public contract&#39;s bids or items with a 200 and <code>Content-Length: 0</code>. The legacy routes opt in to read that as <code>[]</code>; the generated ones throw <code>EsiParseError</code> (<code>JSON_PARSE_ERROR</code>), and resolve a 204 as <code>undefined</code> instead of <code>[]</code>.</td><td><code>contractEndpoints.ts</code> <code>emptyWhenNoContent</code>; <code>PipelineTransport.request</code> passes no flag to <code>handleRequest</code></td><td>Yes</td></tr><tr><td>G6</td><td><strong>Parallel page collection.</strong> The 74 <code>fetchAll*</code> methods fetch the remaining <code>X-Pages</code> pages eight at a time (<code>concurrency</code> is a parameter); <code>paginate</code> on the 40 page-paginated operations fetches pages one after another and yields single items. The 73 <code>stream*</code> methods yield <code>PageResult</code> with <code>page</code> and <code>totalPages</code>, which nothing generated offers.</td><td><code>src/core/pagination/AsyncPaginationIterator.ts</code> <code>fetchAllPages</code>; <code>BaseEsiClient.fetchAllEndpoint</code>, <code>streamEndpoint</code></td><td>Yes</td></tr><tr><td>G7</td><td><strong>Cursor pagination types.</strong> The 12 cursor-paginated operations return one page, like the legacy methods, and the root <code>fetchAllCursorPages</code> can follow them, but not without casts: the generated arrays are <code>readonly</code> (TS4104 against <code>getItems</code>&#39; <code>TItem[]</code>) and <code>exactOptionalPropertyTypes</code> rejects <code>{ before, after }</code> holding <code>undefined</code> (TS2379).</td><td><code>src/core/endpoints/createClient.ts</code> <code>fetchAllCursorPages</code>; generated <code>Get*Params</code></td><td>Yes</td></tr><tr><td>G8</td><td><strong>Response metadata and safe mode.</strong> <code>withMetadata()</code> returns <code>{ data, meta }</code> (ETag, <code>Expires</code>, <code>X-Pages</code>, error-limit headers) and <code>withSafeMode()</code> returns <code>{ ok, data | error }</code> instead of throwing. Neither exists on a view; only a response interceptor sees the headers.</td><td><code>src/clients/BaseEsiClient.ts</code>; <code>createClient.ts</code> <code>buildMeta</code>; guides/ERRORS.md safe mode</td><td>Yes</td></tr><tr><td>G9</td><td><strong>Diagnostics.</strong> <code>EsiClient</code> has <code>diagnostics</code>, <code>getCacheStats</code>, <code>clearCache</code>, <code>updateCacheConfig</code>, <code>getCircuitBreakerStats</code> and <code>resetCircuitBreaker</code>; <code>Esi</code> has only <code>shutdown</code>.</td><td><code>src/EsiClient.ts</code>, <code>src/core/EsiDiagnostics.ts</code>; <code>src/client/runtime.ts</code> <code>Esi</code></td><td>Yes</td></tr><tr><td>G10</td><td><strong>Interceptors after construction.</strong> <code>addRequestInterceptor</code> and <code>addResponseInterceptor</code> add one at any time and return a remover; <code>EsiOptions</code> takes them only at construction. (<code>setAccessToken</code> and <code>setTokenProvider</code> are replaced by design: an <code>Identity</code> per view.)</td><td><code>src/EsiClient.ts</code>; <code>runtime.ts</code> <code>viewClient</code></td><td>No</td></tr><tr><td>G11</td><td><strong>Swapping the middleware.</strong> <code>ApiClientBuilder</code> and the <code>ApiClient</code> setters accept a custom <code>ICache</code>, <code>IRateLimiter</code>, <code>ICircuitBreaker</code> or <code>IDeduplicator</code>. <code>EsiOptions</code> takes their configuration and a <code>retryStrategy</code>, not instances, and the <code>CacheStore</code> and <code>Clock</code> ports <code>./client</code> exports are accepted by nothing.</td><td><code>src/core/ApiClientBuilder.ts</code>; <code>src/client/index.ts</code>; <code>runtime.ts</code> <code>EsiOptions</code></td><td>Yes</td></tr><tr><td>G12</td><td><strong>Configuration differences.</strong> <code>createEsi</code> reads no environment variable (<code>ESI_ACCESS_TOKEN</code>, <code>ESI_BASE_URL</code>, <code>ESI_CLIENT_ID</code>, <code>ESI_DATASOURCE</code>), has no <code>retryAttempts</code> shorthand, requires <code>userAgent</code> where <code>clientId</code> was optional, and its <code>logLevel</code> type rejects <code>&#39;silent&#39;</code>.</td><td><code>src/EsiClient.ts</code> constructor; <code>src/core/EsiClientConfig.ts</code>; <code>runtime.ts</code> <code>EsiOptions</code></td><td>No</td></tr><tr><td>G13</td><td><strong>Batch helpers.</strong> <code>client.batch</code> and <code>client.batchPost</code> log to the client&#39;s logger; the root <code>batchFetch</code> and <code>batchPost</code> work with generated operations but log to the global one, and <code>batchPost</code>&#39;s <code>Promise&lt;T[]&gt;</code> rejects the generated <code>readonly</code> arrays (the G7 typing).</td><td><code>src/core/BatchRequestHandler.ts</code>; <code>src/EsiClient.ts</code> <code>batch</code>, <code>batchPost</code></td><td>No</td></tr><tr><td>G14</td><td><strong>Nameable response types.</strong> <code>./client</code> exports <code>ScopeTree</code> and <code>PublicScopeTree</code> but no response type, so a consumer can name a result only through <code>Awaited&lt;ReturnType&lt;…&gt;&gt;</code>. The root&#39;s hand-written <code>src/types</code> describe the legacy results, and <code>./testing</code>&#39;s <code>TestDataFactory</code> builds those shapes.</td><td><code>src/client/index.ts</code>; <code>src/testing/TestDataFactory.ts</code> imports <code>../types/api-responses</code></td><td>Yes</td></tr><tr><td>G15</td><td><strong>The specification and tests.</strong> The BDD suite drives the legacy clients (<code>npm run spec:coverage:clients</code>: 176 of 384 legacy methods named by a Rule or bound step) through <code>tests/bdd/step-definitions/shared/client-setup.ts</code>. 126 test files reference a deprecated surface, and CHARTER rows cite <code>customClientGetters.test.ts</code> and <code>constructionParity.test.ts</code>. The requirements have to move to the generated operations before the tree goes.</td><td><code>scripts/spec/client-spec-coverage-baseline.json</code>; <code>npm run lint</code> with <code>sonarjs/deprecation</code> on</td><td>Yes</td></tr><tr><td>G16</td><td><strong>Examples and guides.</strong> 51 of the 58 examples use a legacy surface (three use <code>createEsi</code>, four are SDE), and 17 guides plus the README and the site index show one, including <code>ts</code> blocks <code>npm run test:docs-examples</code> type-checks.</td><td><code>examples/</code>, <code>guides/USAGE.md</code> and the rest</td><td>Yes</td></tr><tr><td>G17</td><td><strong>Internal callers.</strong> <code>scripts/quality/live-health.ts</code> (the nightly smoke) runs on <code>EsiClient</code> and counts a response that fails validation as a failure, so it moves after G1.</td><td><code>scripts/quality/live-health.ts</code></td><td>Yes</td></tr><tr><td>G18</td><td><strong>Call shapes.</strong> Legacy methods take positional arguments and build some bodies (<code>postCharacterAssetNames(characterId, itemIds)</code>, <code>getRoute(origin, destination, options)</code> returning <code>route</code>); generated operations take the spec&#39;s body object and return the spec&#39;s shape. A migration table covers it; no capability is lost.</td><td><code>bodyBuilder</code> in the endpoint maps; <code>src/clients/RouteClient.ts</code></td><td>No</td></tr></tbody></table><hr><h2 id="not-decided-yet" tabindex="-1">Not decided yet <a class="header-anchor" href="#not-decided-yet" aria-label="Permalink to &quot;Not decided yet&quot;">​</a></h2><p>These root exports are <strong>not</strong> deprecated in 12.1.0. If 13.0.0 is to remove any of them, a 12.x minor release has to deprecate it first, so decide before the last 12.x release:</p><ul><li><code>TokenProvider</code> and <code>FetchLike</code> from <code>src/core/ApiClient.ts</code>: <code>EsiClientConfig.onTokenRefresh</code> and <code>ApiClientBuilder.setFetch</code> take them. <code>./client</code> has its own <code>TokenProvider</code> port and <code>HttpTransport</code>;</li><li>the branded ID types and <code>brand</code> (<code>src/types/branded.ts</code>) and the <code>EsiSpec</code> namespace of generated spec types.</li></ul><p><code>EsiDatasource</code> stays: <code>EsiOptions</code> uses it.</p><hr><h2 id="lint-while-the-tree-is-deprecated" tabindex="-1">Lint while the tree is deprecated <a class="header-anchor" href="#lint-while-the-tree-is-deprecated" aria-label="Permalink to &quot;Lint while the tree is deprecated&quot;">​</a></h2><p><code>sonarjs/deprecation</code> reports every use of a deprecated declaration. <code>eslint.config.mjs</code> turns it off only where the deprecated surfaces refer to one another or are under test, each with its reason in the config:</p><ul><li>in <code>src/</code> and <code>scripts/</code>: the construction tree (<code>src/EsiClient.ts</code>, <code>src/EsiClientBuilder.ts</code>, <code>src/clients/</code>, <code>src/core/ApiClientBuilder.ts</code>), the response types (<code>src/types/*.ts</code> and <code>src/types/generated/spec-alignment.check.ts</code>), <code>src/core/endpoints/createClient.ts</code>, <code>src/testing/TestDataFactory.ts</code>, <code>src/auth/EsiTokenManager.ts</code> and <code>scripts/quality/live-health.ts</code> (G17). A new use anywhere else is still an error;</li><li>in <code>tests/</code>: the 135 files in <code>config/eslint/legacy-tests.cjs</code>, which test the deprecated surfaces. Everywhere else in <code>tests/</code> it stays a warning held by <code>npm run lint:ratchet</code>, so a new use of a deprecated API is still caught. A file leaves the list when it moves to <code>createEsi()</code>, and 13.0.0 deletes the list with the files.</li></ul>',28)])])}const g=t(r,[["render",a]]);export{u as __pageData,g as default};
